// ActionsResource groups the Actions operations.
type ActionsResource struct {
	transport *runtime.Transport
}

// DisableWorkflow disables a workflow (ActionsDisableWorkflow).
func (r *ActionsResource) DisableWorkflow(ctx context.Context, owner string, repo string, workflowID string) error {
	_, err := runtime.Call[any](ctx, r.transport, opActionsDisableWorkflow, runtime.Input{Path: []any{owner, repo, workflowID}})
	return err
}

// ActionsDispatchWorkflowParams holds the query parameters of [ActionsResource.DispatchWorkflow]. Set only what you need.
type ActionsDispatchWorkflowParams struct {
	ReturnRunDetails           *bool  `query:"return_run_details"`
	ScopedWorkflowSourceRepoID *int64 `query:"scoped_workflow_source_repo_id"`
}

// DispatchWorkflow starts a workflow run by hand (ActionsDispatchWorkflow).
func (r *ActionsResource) DispatchWorkflow(ctx context.Context, owner string, repo string, workflowID string, body *CreateActionWorkflowDispatch, params *ActionsDispatchWorkflowParams) (*RunDetails, error) {
	return runtime.Call[*RunDetails](ctx, r.transport, opActionsDispatchWorkflow, runtime.Input{Path: []any{owner, repo, workflowID}, Body: body, Params: params})
}

// EnableWorkflow enables a workflow (ActionsEnableWorkflow).
func (r *ActionsResource) EnableWorkflow(ctx context.Context, owner string, repo string, workflowID string) error {
	_, err := runtime.Call[any](ctx, r.transport, opActionsEnableWorkflow, runtime.Input{Path: []any{owner, repo, workflowID}})
	return err
}

// GetWorkflow gets a workflow (ActionsGetWorkflow).
func (r *ActionsResource) GetWorkflow(ctx context.Context, owner string, repo string, workflowID string) (*ActionWorkflow, error) {
	return runtime.Call[*ActionWorkflow](ctx, r.transport, opActionsGetWorkflow, runtime.Input{Path: []any{owner, repo, workflowID}})
}

// ListWorkflows lists a repository's workflows (ActionsListRepositoryWorkflows).
func (r *ActionsResource) ListWorkflows(ctx context.Context, owner string, repo string) (*ActionWorkflowResponse, error) {
	return runtime.Call[*ActionWorkflowResponse](ctx, r.transport, opActionsListRepositoryWorkflows, runtime.Input{Path: []any{owner, repo}})
}

// ActionsListWorkflowRunsParams holds the query parameters of [ActionsResource.ListWorkflowRuns]. Set only what you need.
